// slang-ir-lower-bit-cast.h
#pragma once

// This file defines an IR pass that lowers a BitCast<T>(U) operation, where T and U are struct
// types, into a series of bit-cast operations on basic-typed elements. It also defines a
// diagnostic pass that rejects user casts into a `DescriptorHandle<T>` and runs before AnyValue
// marshalling and byte-address-buffer legalization. As a result, the casts into a handle that
// reach `lowerBitCast` are either generated by those passes or, on a bindless target, a cast of a
// resource to its own handle type.
//
// A bindless target is one for which `areResourceTypesBindlessOnTarget` holds (CUDA, CPU and
// Metal): there a handle is the native resource. Elsewhere a handle is an integer value: a `uint2`
// heap index, or a `uint64_t` for texture and sampler kinds under `spvBindlessTextureNV`.

namespace Slang
{

struct IRModule;
class DiagnosticSink;
class TargetProgram;

/// Lower every `BitCast` between composite types into leaf-level casts, reporting E41202 for a size
/// mismatch. A cast into a bare handle is left for the target to emit. A cast out of a bare handle
/// reads the handle's integer value on a non-bindless target and is left for the target on a
/// bindless one. A struct or array source that contains a handle is still lowered byte-wise, which
/// reads the handle as one 64-bit leaf; WGSL cannot express that and GLSL keeps only the low word.
void lowerBitCast(IRModule* module, TargetProgram* targetReq, DiagnosticSink* sink);

/// Report an error for every `BitCast` whose destination type is or contains a
/// `DescriptorHandle<T>`, unless the operand has the same type, or the target is bindless and the
/// operand is the bare resource the handle wraps.
///
/// A handle's representation differs between bindless and non-bindless targets, so a bit pattern
/// produced from other data means different things on different targets. We therefore treat a
/// `bit_cast` into a handle as ill-formed and leave construction to the `DescriptorHandle`
/// constructors; a `bit_cast` out of a bare handle stays an ordinary same-size reinterpretation.
/// On a bindless target the handle is its resource, so a resource cast to its own handle type
/// changes nothing and is accepted there. The check must run before AnyValue marshalling
/// and byte-address-buffer legalization, because both build handles with their own `BitCast` and
/// nothing in the IR tells those casts apart from the user's.
void diagnoseBitCastsToDescriptorHandle(
    IRModule* module,
    TargetProgram* targetProgram,
    DiagnosticSink* sink);

} // namespace Slang
